 "content": "def transform(grid):
    out = [[0 for _ in row] for row in grid]
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not cells:
        return out
    bottom = max(r for r, c, v in cells)
    for r, c, v in cells:
        nc = c - (bottom - r)
        if 0 <= nc < len(grid[0]):
            out[r][nc] = v
    return out
